// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a concrete scenario: first call getFreeKilo, then buyDrugs, then seedMarket
        // But the bug is about initialized being set to true in seedMarket
        vm.deal(address(this), 1 ether);
        // Call getFreeKilo to mint some kilos
        c.getFreeKilo();
        // Call buyDrugs to add drugs to market
        c.buyDrugs{value: 0.1 ether}();
        // Call seedMarket to initialize
        c.seedMarket(100);
        // After seedMarket, check initialized
        bool initialized = c.initialized();
        // The reference sets initialized to true, the buggy version does not
        assertTrue(initialized);
    }
}

