pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // seed the market with 1 ether worth of drugs (any value works)
        c.seedMarket{value: 1 ether}(1 ether);

        // call DrugDealer() – triggers the divergence in initialized
        c.DrugDealer();

        // now call getFreeKilo() – requires initialized to be true
        // In the reference, initialized == true, so it succeeds.
        // In the buggy version, initialized == false, so it reverts.
        bool ok = false;
        try c.getFreeKilo() { ok = true; } catch { ok = false; }

        // reference passes (ok == true), bug fails (ok == false)
        assertTrue(ok);
    }
}

