// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy with default ceoAddress = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26
        // Simulate initial setup: call seedMarket to initialize, getFreeKilo for a user
        address user = address(0x123);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.seedMarket{value: 0}(1000);

        // user gets free kilos
        vm.prank(user);
        c.getFreeKilo();

        // Warp time so user accrues drugs
        vm.warp(block.timestamp + 86400); // 1 day

        // Now the current ceoAddress calls DrugDealer to change to a new address
        address newCeo = address(0x456);
        vm.prank(c.ceoAddress());
        // In reference, ceoAddress becomes newCeo; in mutant, it stays as old
        c.DrugDealer();

        // After DrugDealer, the reference has newCeo, mutant still has old
        // Let user buy drugs with some eth to increase balance
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.buyDrugs{value: 1 ether}();

        // Now user sells drugs; the fee (4%) should go to ceoAddress
        // In reference, ceoAddress = newCeo, so fee goes to newCeo
        // In mutant, ceoAddress = old, fee goes to old
        uint256 balanceBefore = address(newCeo).balance;
        vm.prank(user);
        c.sellDrugs();
        uint256 balanceAfter = address(newCeo).balance;

        // In reference, newCeo got fee (non-zero); in mutant, newCeo got 0
        assertTrue(balanceAfter > balanceBefore);
    }
}

