// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up initial state: seed market with 1000 drugs and send Ether
        address dealer = makeAddr("dealer");
        vm.deal(dealer, 10 ether);
        vm.startPrank(dealer);
        c.seedMarket{value: 10 ether}(1000);
        vm.stopPrank();

        // Get free kilo for user1 to earn drugs
        address user1 = makeAddr("user1");
        vm.prank(user1);
        c.getFreeKilo();

        // Warp forward so user1 earns some drugs
        vm.warp(block.timestamp + 86400); // 1 day

        // User1 collects drugs, triggering referral logic; this gives user1 claimable drugs
        vm.prank(user1);
        c.collectDrugs(address(0));

        // Now user1 calls DrugDealer; in reference ceoAddress becomes user1, in bug it stays original
        vm.prank(user1);
        c.DrugDealer();

        // Record user1's balance before sell
        uint256 user1BalanceBefore = user1.balance;

        // User1 sells drugs; in reference the CEO fee (4%) goes to user1 (new ceoAddress); in bug it goes to original ceoAddress
        vm.prank(user1);
        c.sellDrugs();

        // Check user1's balance after sell; in reference it increased, in bug it did not (or less)
        uint256 user1BalanceAfter = user1.balance;
        // In reference, user1 received the sell value minus fee; fee went to user1 as well, so user1 net should be sell value (since fee goes to himself)
        // In bug, fee goes to original ceoAddress, so user1 gets less
        // We assert that user1 gained at least the contract's balance (minus negligible rounding)
        // This is a concrete diverging fact: reference passes, bug fails because user1 receives less
        assertTrue(user1BalanceAfter > user1BalanceBefore, "User1 should have gained Ether from sell");
    }
}

