pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // seed the market with 100 drugs and 10 ether
        vm.deal(address(0x100), 1 ether);
        vm.prank(address(0x100));
        c.seedMarket{value: 0.1 ether}(100);

        // user gets free kilo
        address user = address(0x200);
        address referrer = address(0x300);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.getFreeKilo();

        // warp time by 1 second to accumulate drugs (1 kilo per second)
        vm.warp(block.timestamp + 1);

        // user collects drugs with referrer
        vm.prank(user);
        c.collectDrugs(referrer);

        // In reference: referrer gets drugsUsed/5 = 1/5 = 0 (integer division)
        // Actually: with 1 second, getMyDrugs = 1 (since 1 kilo * 1 second)
        // Wait — need drugsUsed >= 86400 for even 1 referral reward. So let's use larger time.
        // Reset: warp time by 86400 seconds to produce exactly 1*86400 = 86400 drugs
        vm.warp(block.timestamp + 86400);

        // user collects again (referrer already set)
        vm.prank(user);
        c.collectDrugs(referrer);

        // Now drugsUsed = 86400; reference: referrer gets 86400/5 = 17280; bug: 86400/10 = 8640
        // Assert that referrer's claimedDrugs is NOT 8640 (the buggy value)
        assertTrue(c.claimedDrugs(referrer) != 8640);
    }
}

