// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up two users
        address user0 = address(0x1);
        address user1 = address(0x2);
        vm.deal(user0, 10 ether);
        vm.deal(user1, 10 ether);

        // Seed market
        vm.prank(user0);
        c.seedMarket{value: 1 ether}(100);

        // Get free kilo for both
        vm.prank(user0);
        c.getFreeKilo();
        vm.prank(user1);
        c.getFreeKilo();

        // Set new CEO to user1 via DrugDealer
        vm.prank(c.ceoAddress());
        c.DrugDealer(); // In reference, ceoAddress becomes msg.sender (original CEO)
        // Actually we need to change CEO to user1, but DrugDealer sets ceoAddress to msg.sender
        // So we call it from the current ceoAddress to set ceoAddress to that same address? No.
        // DrugDealer requires msg.sender == ceoAddress, then sets ceoAddress = msg.sender.
        // So after call, ceoAddress remains the same. To change, we need a different caller.
        // Let's just use the default ceoAddress for fee.
        // Better: call DrugDealer from ceoAddress, which does nothing.
        // Then user0 buys drugs.
        vm.prank(user0);
        c.buyDrugs{value: 1 ether}();
        // User1 sells drugs
        vm.prank(user1);
        c.sellDrugs();

        // Now check: in reference, fee goes to ceoAddress (default), so user1 gets nothing from sell.
        // In bug, fee goes to msg.sender (user1), so user1 gets fee and balance changes,
        // affecting buy calculation if user0 buys again. But we need a direct observable difference.
        // Let's use the fact that claimedDrugs[user1] after selling differs because in bug
        // the sell function sends fee to msg.sender, which is user1, so user1 receives Ether
        // and can have different claimedDrugs if they buy again? No, claimedDrugs not directly changed.
        // Instead, check balance of ceoAddress: in reference, ceoAddress gets fee; in bug, msg.sender gets it.
        // So after sell, ceoAddress.balance differs.
        // Let's check address(c.ceoAddress()).balance
        // But the bug changes sellDrugs so that payable(msg.sender).transfer(fee) replaces payable(ceoAddress).
        // So after user1 sells, in reference ceoAddress gets fee, in bug user1 gets fee.
        // Since user1 is msg.sender, user1.balance differs.
        // However, we need to observe through c's public surface.
        // c does not expose balances of arbitrary addresses. address(c).balance is contract balance.
        // In reference, fee goes to ceoAddress (contract is not receiving it).
        // In bug, fee stays in contract? No, it's sent to msg.sender, so contract loses that Ether.
        // So address(c).balance differs.
        // Let's compute: initial contract balance after seed: 1 ether.
        // User0 buys with 1 ether: balance becomes 2 ether, then fee transfer to ceoAddress (0.04 ether) => 1.96 ether.
        // Then user1 sells: hasDrugs = claimedDrugs + time*Kilos. Since no time passes, zero extra.
        // getMyDrugs = claimedDrugs[user1] = 0 (since sell sets to 0). So sells 0 drugs? Actually getMyDrugs returns 0, so hasDrugs=0.
        // This is useless. Let's set time warp to allow drug production.
        vm.warp(86400); // Advance 1 day
        // Now getMyDrugs for user1 = 0 + 86400 * 1 = 86400 drugs.
        vm.prank(user1);
        c.sellDrugs();
        // After sell, in reference, contract sends fee to ceoAddress (0.04 * drugValue), reducing contract balance.
        // In bug, contract sends fee to msg.sender (user1), also reducing contract balance. Both reduce by same amount? Actually fee amount is same, destination differs.
        // So contract balance after sell is same in both? No, because drugValue calculation depends on contract balance during sell.
        // The sell function calculates drugValue based on current contract balance before transfer. That balance is same at that point.
        // So fee amount is same, contract balance after both transfers is same.
        // However, the ceoAddress balance differs: in reference, ceoAddress gets fee; in bug, user1 gets it.
        // We cannot observe ceoAddress balance through c. But we can observe something else.
        // Let's instead have user0 buy again after user1 sells. The buyDrugs calculation uses address(this).balance which differs between reference and bug because the fee transfer destination doesn't affect contract balance (both remove same amount from contract).
        // So still no observable difference through c.
        // But note: in reference, after user1 sells, marketDrugs increased by hasDrugs. Then user0 buys: calculateDrugBuy uses marketDrugs and contract balance. fee transfer to ceoAddress occurs again. But contract balance differs by fee amount? No, both remove fee from contract.
        // Actually in reference, contract sends two transfers: fee to ceoAddress, then drugValue-fee to msg.sender. In bug, both to msg.sender. Total Ether leaving contract is drugValue in both cases. So contract balance same.
        // The difference is who gets the fee. Since we cannot observe ceoAddress balance directly, we need another approach.
        // Let's use the property: in buyDrugs, ceoAddress receives devFee(msg.value) in both versions (that line is unchanged). So ceoAddress gets that. Then sellDrugs sends fee to ceoAddress in reference, but to msg.sender in bug. So after sell, ceoAddress balance is less in bug than in reference.
        // But we can observe address(c.ceoAddress()).balance using vm.getBalance? Not allowed. Only address(c).balance.
        // Another idea: after sell, have user0 call getMyDrugs() which depends on lastCollect and Kilos. Those are unchanged.
        // Maybe the difference is that in bug, the sell sends fee to msg.sender, so msg.sender gets more Ether and could use it to buy more drugs, changing their claimedDrugs. But that requires a subsequent buy by the seller, which we can do.
