pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed market so initialized = true and marketDrugs != 0
        vm.deal(address(this), 10 ether);
        c.seedMarket{value: 1 ether}(1000);

        // Set ceoAddress to something distinct
        address ceo = makeAddr("ceo");
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26); // default ceo
        c.DrugDealer(); // sets ceoAddress to msg.sender = default ceo
        // Actually above doesn't change, let's just use the default ceo address

        address user = makeAddr("user");
        vm.deal(user, 5 ether);
        vm.prank(user);
        c.buyDrugs{value: 2 ether}();

        // In reference: fee sent to ceoAddress (0x85ab...), user gets drugsBought
        // In bug: fee sent to user, so user's claimedDrugs includes extra devFee
        uint256 userClaimedRef = c.claimedDrugs(user);
        // Reference calculation: drugsBought = calculateDrugBuy(2e18, 1e18) - devFee(drugsBought)
        // devFee = 4% of drugsBought; bug adds that back to user
        uint256 devFeeAmount = c.devFee(c.calculateDrugBuySimple(2 ether)); // approximate
        uint256 userClaimedBug = userClaimedRef + devFeeAmount;

        // The actual behavior: user's claimedDrugs should be lower in reference than in bug
        assertTrue(c.claimedDrugs(user) < userClaimedBug);
    }
}

