pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address ceo = makeAddr("ceo");
        address user = makeAddr("user");

        // Seed market and initialize
        vm.deal(ceo, 100 ether);
        vm.prank(ceo);
        c.seedMarket{value: 100 ether}(100000);

        // CEO claims free kilos
        vm.prank(ceo);
        c.getFreeKilo();

        // User gets free kilos
        vm.prank(user);
        c.getFreeKilo();

        // CEO calls DrugDealer to set new CEO (this is needed) - but keep original ceo
        // Actually, let's just use the original ceo as is
        // User buys drugs with 1 wei, referring CEO
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.buyDrugs{value: 1 wei}();

        // Wait some time, then CEO collects drugs
        vm.warp(block.timestamp + 100000);
        vm.prank(ceo);
        c.collectDrugs(address(0));

        // In reference, ceo's claimedDrugs are 0 (fee went to ceoAddress, not claimed)
        // In mutant, fee went to user which then gets split: 1/5 to referral (ceo)
        assertTrue(c.claimedDrugs(ceo) == 0);
    }
}

