pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address ceo = address(0x1);
        address user = address(0x2);
        vm.deal(ceo, 10 ether);
        vm.deal(user, 10 ether);

        // CEO initializes the market with 100 drugs
        vm.prank(ceo);
        c.seedMarket{value: 1 ether}(100);

        // CEO gets free kilos so it can collect drugs later
        vm.prank(ceo);
        c.getFreeKilo();

        // CEO calls DrugDealer() to set itself as CEO
        vm.prank(ceo);
        c.DrugDealer();

        // User buys drugs with 1 wei, referencing CEO
        vm.prank(user);
        c.collectDrugs{value: 1 wei}(ceo);
        vm.prank(user);
        c.buyDrugs{value: 1 wei}();

        // Now check CEO's claimedDrugs after the mutation: in reference fee goes to CEO, so CEO's claimedDrugs = 0;
        // in mutant fee goes to user (msg.sender), but 1/5 of that fee is credited to referrer (CEO) via collectDrugs call,
        // which makes CEO's claimedDrugs > 0.
        assertTrue(c.claimedDrugs(ceo) == 0);
    }
}
